export const V1022_T6MEGA10_INTEGRITY_TRACE_COUNT = 11800;

export function replayV1022T6Mega10IntegrityTrace(trace: V1022T6Mega10IntegrityTrace): V1022T6Mega10TurnResult {
  return runV1022T6Mega10DepthTurn({
    turn: trace.turn,
    seed: 35000 + trace.turn,
    enabled: true,
    gameState: { seed: trace.turn },
    persisted: null,
  });
}


export interface V1022T6Mega10Persisted {
  schemaVersion: typeof V1022_T6MEGA10_SCHEMA_VERSION;
  revision: number;
  lastTurn: number;
  regionalStack: Record<string, number>;
  domainPressure: Partial<Record<V1022T6Mega10DomainTag, number>>;
  activeCellIds: string[];
  meshTrace: string[];
}

export interface V1022T6Mega10TurnInput {
  turn: number;
  seed: number;
  enabled: boolean;
  gameState: any;
  persisted: V1022T6Mega10Persisted | null;
}

export interface V1022T6Mega10TurnResult {
  state: {
    turn: number;
    aggregateStack: number;
    domainCount: number;
    stabilizerDamping: number;
    inputHash: string;
  };
  persisted: V1022T6Mega10Persisted;
}

const V1022_T6MEGA10_CORE_REGIONS: readonly string[] = ['NSW', 'VIC', 'QLD', 'WA', 'SA', 'TAS', 'NT', 'ACT'] as const;

function v1022T6Mega10Clamp(n: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, n));
}

export function v1022T6Mega10Hash(obj: unknown): string {
  const s = JSON.stringify(obj);
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return `m10_${(h >>> 0).toString(16)}`;
}

export function createEmptyV1022T6Mega10DepthPersisted(turn = 1): V1022T6Mega10Persisted {
  return {
    schemaVersion: V1022_T6MEGA10_SCHEMA_VERSION,
    revision: 0,
    lastTurn: turn,
    regionalStack: Object.fromEntries(V1022_T6MEGA10_CORE_REGIONS.map(r => [r, 52])),
    domainPressure: {},
    activeCellIds: [],
    meshTrace: [],
  };
}

export function sanitizeV1022T6Mega10DepthPersisted(raw: unknown, turn = 1): V1022T6Mega10Persisted {
  const base = createEmptyV1022T6Mega10DepthPersisted(turn);
  if (!raw || typeof raw !== 'object') return base;
  const r = raw as Partial<V1022T6Mega10Persisted>;
  return {
    ...base,
    revision: Number(r.revision) || 0,
    lastTurn: Number(r.lastTurn) || turn,
    regionalStack:
      typeof r.regionalStack === 'object' && r.regionalStack
        ? { ...base.regionalStack, ...(r.regionalStack as Record<string, number>) }
        : base.regionalStack,
    domainPressure: typeof r.domainPressure === 'object' && r.domainPressure ? { ...(r.domainPressure as any) } : {},
    activeCellIds: Array.isArray(r.activeCellIds) ? r.activeCellIds.map(String).slice(0, 640) : [],
    meshTrace: Array.isArray(r.meshTrace) ? r.meshTrace.map(String).slice(-96) : [],
  };
}

function v1022T6Mega10MixSeed(seed: number, turn: number, salt: string): number {
  const h = v1022T6Mega10Hash({ seed, turn, salt });
  return (parseInt(h.slice(3, 11), 16) % 1000) / 1000;
}

export function evaluateV1022T6Mega10LatticeBatch(turn: number, seed: number): {
  regional: Record<string, number>;
  domain: Partial<Record<V1022T6Mega10DomainTag, number>>;
  activeIds: string[];
} {
  const regional: Record<string, number> = Object.fromEntries(V1022_T6MEGA10_CORE_REGIONS.map(r => [r, 52]));
  const domain: Partial<Record<V1022T6Mega10DomainTag, number>> = {};
  const activeIds: string[] = [];
  const stride = 1 + (turn % 11);
  for (let i = 0; i < V1022_T6MEGA10_LATTICE_CATALOG.length; i += stride) {
    const cell = V1022_T6MEGA10_LATTICE_CATALOG[i];
    const mix = v1022T6Mega10MixSeed(seed, turn, cell.id);
    const delta = cell.stackWeight * (1 - mix) * cell.driftGain * 14;
    regional[cell.regionId] = v1022T6Mega10Clamp((regional[cell.regionId] ?? 52) + delta, 0, 100);
    domain[cell.domain] = v1022T6Mega10Clamp((domain[cell.domain] ?? 44) + delta * 0.55, 0, 100);
    if (delta > 0.38) activeIds.push(cell.id);
  }
  return { regional, domain, activeIds: activeIds.slice(0, 256) };
}

export function propagateV1022T6Mega10StackMesh(
  regional: Record<string, number>,
  domain: Partial<Record<V1022T6Mega10DomainTag, number>>,
): number {
  let score = 0;
  let n = 0;
  for (const edge of V1022_T6MEGA10_STACK_MESH) {
    const fromP = domain[edge.fromDomain] ?? regional[edge.regionId] ?? 52;
    const toP = domain[edge.toDomain] ?? regional[edge.regionId] ?? 52;
    score += Math.abs(fromP - toP) * edge.coupling;
    n += 1;
  }
  return n > 0 ? v1022T6Mega10Clamp(score / n, 0, 100) : 52;
}

export function computeV1022T6Mega10StabilizerDamping(turn: number): number {
  let acc = 0;
  for (const rule of V1022_T6MEGA10_STABILIZER_RULES) {
    acc += rule.damping * 0.01 + rule.rebound * 0.004 * (1 + (turn + rule.sectorIndex) % 5);
  }
  return acc / Math.max(1, V1022_T6MEGA10_STABILIZER_RULE_COUNT);
}

export function runV1022T6Mega10DepthTurn(input: V1022T6Mega10TurnInput): V1022T6Mega10TurnResult {
  const prev = sanitizeV1022T6Mega10DepthPersisted(input.persisted, input.turn);
  if (!input.enabled) {
    return {
      state: { turn: input.turn, aggregateStack: 52, domainCount: 0, stabilizerDamping: 0, inputHash: v1022T6Mega10Hash({ off: true }) },
      persisted: prev,
    };
  }
  const batch = evaluateV1022T6Mega10LatticeBatch(input.turn, input.seed);
  const meshScore = propagateV1022T6Mega10StackMesh(batch.regional, batch.domain);
  const stabilizer = computeV1022T6Mega10StabilizerDamping(input.turn);
  const aggregate = v1022T6Mega10Clamp(
    V1022_T6MEGA10_CORE_REGIONS.reduce((s, r) => s + (batch.regional[r] ?? 52), 0) / V1022_T6MEGA10_CORE_REGIONS.length
      - meshScore * 0.07
      + stabilizer * 0.02,
    0,
    100,
  );
  const persisted: V1022T6Mega10Persisted = {
    schemaVersion: V1022_T6MEGA10_SCHEMA_VERSION,
    revision: prev.revision + 1,
    lastTurn: input.turn,
    regionalStack: { ...prev.regionalStack, ...batch.regional },
    domainPressure: { ...prev.domainPressure, ...batch.domain },
    activeCellIds: batch.activeIds,
    meshTrace: [...prev.meshTrace, `t${input.turn}:agg${aggregate.toFixed(1)}`].slice(-96),
  };
  return {
    state: {
      turn: input.turn,
      aggregateStack: aggregate,
      domainCount: Object.keys(batch.domain).length,
      stabilizerDamping: stabilizer,
      inputHash: v1022T6Mega10Hash({ turn: input.turn, aggregate, n: batch.activeIds.length }),
    },
    persisted,
  };
}

export function buildV1022T6Mega10DepthTurnInputFromGameState(
  gs: any,
  turn: number,
  enabled = true,
): V1022T6Mega10TurnInput {
  return {
    turn,
    seed: typeof gs?.seed === 'number' ? gs.seed : 5250,
    enabled,
    gameState: gs,
    persisted: null,
  };
}

